// Handle multiple response formats
let data = $json;

// Try parsing if string
if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (e) {
    console.log('Not JSON string');
  }
}

// Extract jobs from various paths
const jobs = data.results || 
             data.jobs || 
             data.data?.results || 
             [];

console.log(`Adzuna: Found ${jobs.length} jobs`);

if (jobs.length === 0) {
  console.log('Full response:', JSON.stringify(data).substring(0, 500));
  return [{
    json: {
      source: 'Adzuna',
      jobs: [],
      error: 'No jobs in response',
      raw_keys: Object.keys(data)
    }
  }];
}

return jobs.map(job => ({
  json: {
    title: job.title || '',
    company: job.company?.display_name || 'Unknown',
    location: job.location?.display_name || 'India',
    url: job.redirect_url || '',
    description: job.description || '',
    salary: job.salary_min && job.salary_max ? 
      `₹${(job.salary_min/100000).toFixed(1)}-${(job.salary_max/100000).toFixed(1)} LPA` : '',
    source: 'Adzuna',
    posted_date: job.created || new Date().toISOString()
  }
}));

const items = [];

for (const item of $input.all()) {
  const jobs = item.json.jobs_results || [];

  for (const job of jobs) {
    items.push({
      json: {
        title: job.title || '',
        company: job.company_name || '',
        location: job.location || '',
        url: job.share_link || (job.apply_options?.[0]?.link || ''),
        description: job.description || '',
        salary: job.detected_extensions?.salary || '',
        source: 'SerpAPI',
        posted_date: job.detected_extensions?.posted_at || new Date().toISOString()
      }
    });
  }
}

return items;

// FIX #3: Improved deduplication with URL normalization
const allJobs = [];
const seenUrls = new Set();
const today = new Date().toISOString().split('T')[0];

// Helper function to normalize URLs
function normalizeUrl(url) {
  if (!url) return '';

  try {
    const urlObj = new URL(url);
    // Remove query parameters and fragments for deduplication
    const normalized = `${urlObj.protocol}//${urlObj.host}${urlObj.pathname}`;
    return normalized.toLowerCase().replace(/\/$/, ''); // Remove trailing slash
  } catch (error) {
    // If URL parsing fails, just use lowercase without query params
    return url.split('?')[0].split('#')[0].toLowerCase();
  }
}

// Process all input items
for (const item of $input.all()) {
  let jobs = [];

  try {
    // LinkedIn RSS format
    if (item.json.title && item.json.link) {
      jobs = [{
        title: item.json.title || '',
        company: item.json.creator || item.json['dc:creator'] || 'Unknown',
        location: item.json.location || 'India',
        url: item.json.link || '',
        description: item.json.contentSnippet || item.json.content || item.json.description || '',
        salary: '',
        source: 'LinkedIn',
        posted_date: item.json.pubDate || item.json.isoDate || today
      }];
    }
    // SerpAPI Google Jobs format
    else if (item.json.jobs_results) {
      jobs = item.json.jobs_results.map(job => ({
        title: job.title || '',
        company: job.company_name || '',
        location: job.location || '',
        url: job.share_url || job.related_links?.[0]?.link || '',
        description: job.description || '',
        salary: job.detected_extensions?.salary || '',
        source: 'Google Jobs',
        posted_date: job.detected_extensions?.posted_at || today
      }));
    }
    // Naukri.com format (from our parser)
    else if (item.json.source === 'Naukri.com') {
      jobs = [{
        title: item.json.title || '',
        company: item.json.company || '',
        location: item.json.location || '',
        url: item.json.url || '',
        description: item.json.description || '',
        salary: item.json.salary || '',
        source: 'Naukri.com',
        posted_date: today
      }];
    }
    // Generic format (fallback)
    else if (item.json.title) {
      jobs = [{
        title: item.json.title || '',
        company: item.json.company || item.json.company_name || '',
        location: item.json.location || '',
        url: item.json.url || item.json.link || '',
        description: item.json.description || '',
        salary: item.json.salary || '',
        source: item.json.source || 'Other',
        posted_date: item.json.posted_date || item.json.date || today
      }];
    }
  } catch (error) {
    console.log('Error processing item:', error);
    continue;
  }

  // Add jobs to collection with improved deduplication
  for (const job of jobs) {
    // Skip if missing essential fields
    if (!job.url || !job.title || !job.company) continue;

    // FIX #3: Normalize URL before checking duplicates
    const normalizedUrl = normalizeUrl(job.url);
    if (!normalizedUrl) continue;

    // Skip duplicates
    if (seenUrls.has(normalizedUrl)) {
      console.log(`Duplicate detected: ${job.title} at ${job.company}`);
      continue;
    }
    seenUrls.add(normalizedUrl);

    // Basic filtering - must be software/SDE related
    const titleLower = job.title.toLowerCase();
    const descLower = job.description.toLowerCase();

    const relevantKeywords = [
      'software', 'developer', 'engineer', 'sde', 'full stack',
      'frontend', 'backend', 'react', 'node', 'javascript', 'java',
      'python', 'web', 'mobile', 'app'
    ];

    const isRelevant = relevantKeywords.some(keyword => 
      titleLower.includes(keyword) || descLower.includes(keyword)
    );

    if (isRelevant) {
      // Add metadata
      job.found_date = today;
      job.processed = false;
      job.normalized_url = normalizedUrl; // Keep for debugging
      allJobs.push(job);
    }
  }
}

// Sort by posted date (newest first)
allJobs.sort((a, b) => {
  const dateA = new Date(a.posted_date);
  const dateB = new Date(b.posted_date);
  return dateB - dateA;
});

// Limit to top 20 jobs to stay within API limits
const limitedJobs = allJobs.slice(0, 50);

console.log(`Total jobs found: ${allJobs.length}, Duplicates removed: ${$input.all().length - allJobs.length}, Processing: ${limitedJobs.length}`);

if (limitedJobs.length === 0) {
  return [{ json: { message: 'No jobs found today', jobs_found: 0 } }];
}

return limitedJobs.map(job => ({ json: job }));

// Generate daily summary
const allJobs = $input.all();

if (allJobs.length === 0 || allJobs[0].json.message === 'No jobs found today') {
  return [{
    json: {
      date: new Date().toISOString().split('T')[0],
      total_jobs_found: 0,
      jobs_processed: 0,
      avg_ats_score: 0,
      recruiters_found: 0,
      high_match_jobs: 0,
      companies: [],
      status: 'No new jobs today'
    }
  }];
}

const processedJobs = allJobs.filter(j => j.json.tailoredResume);

// Count high-confidence recruiters
const highConfidenceRecruiters = allJobs.filter(j => 
  j.json.recruiter?.recruiter_email && 
  j.json.recruiter.recruiter_email !== 'Not Found' &&
  j.json.recruiter.confidence === 'high'
).length;

const mediumConfidenceRecruiters = allJobs.filter(j => 
  j.json.recruiter?.recruiter_email && 
  j.json.recruiter.recruiter_email !== 'Not Found' &&
  j.json.recruiter.confidence === 'medium'
).length;

const summary = {
  date: new Date().toISOString().split('T')[0],
  total_jobs_found: allJobs.length,
  jobs_processed: processedJobs.length,
  avg_ats_score: Math.round(
    processedJobs.reduce((sum, j) => sum + (j.json.tailoredResume?.ats_score || 0), 0) / 
    (processedJobs.length || 1)
  ),
  recruiters_found: highConfidenceRecruiters + mediumConfidenceRecruiters,
  high_confidence_recruiters: highConfidenceRecruiters,
  medium_confidence_recruiters: mediumConfidenceRecruiters,
  high_match_jobs: processedJobs.filter(j => 
    (j.json.tailoredResume?.ats_score || 0) >= 70
  ).length,
  companies: [...new Set(allJobs.map(j => j.json.company))],
  sources: [...new Set(allJobs.map(j => j.json.source))],
  status: 'Processing complete'
};

console.log('Daily Summary:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
